#!/usr/bin/env node
/**
 * sync-videsign-tokens.mjs — Deterministic videsign token synchronization.
 *
 * Reads a source tokens.json (and optionally glass.css) generated by videsign
 * at a specific SHA, validates them, and writes tracked CSS artifacts with
 * provenance.
 *
 * Usage:
 *   node scripts/sync-videsign-tokens.mjs \
 *     --source videsign-tokens-source.json \
 *     --glass videsign-glass-source.css \
 *     --sha <videsign commit sha>
 *
 * Optional: --out <path> and --glass-out <path> redirect the generated files
 * (tests use them so they never touch tracked artifacts). Relative paths
 * resolve against the repository root; absolute paths pass through.
 *
 * Fails closed when:
 *   - source file missing or malformed
 *   - SHA missing
 *   - a required token is missing
 *   - any `typography-fluid-*` token is unparseable or exceeds 3.5rem. Only
 *     `typography-fluid-hero-base` may exceed it, and only to exactly 5.25rem
 *   - the glass stylesheet is missing or lacks literal backdrop declarations
 *
 * The generated artifacts record the source repository, exact source SHA and
 * the generation command.
 */
import { readFileSync, writeFileSync, existsSync } from "node:fs";
import { join, dirname, isAbsolute } from "node:path";
import { fileURLToPath } from "node:url";
import { syncViDesignStandardFiles } from "./lib/videsign-standard.mjs";

const __dirname = dirname(fileURLToPath(import.meta.url));
const ROOT = __dirname;

const args = process.argv.slice(2);
/** @param {string} name @returns {string | null} */
const flag = (name) => {
  const i = args.indexOf(`--${name}`);
  const value = i >= 0 ? args[i + 1] : undefined;
  return value ?? null;
};
const sourcePath = flag("source");
const sourceSha = flag("sha");
const glassPath = flag("glass");
const outArg = flag("out");
const glassOutArg = flag("glass-out");

/** @param {string} message @returns {never} */
const fail = (message) => {
  console.error(`[tokens] ${message}`);
  process.exit(1);
};
// Absolute paths pass through; relative paths resolve against the repo root.
/** @param {string} p */
const resolvePath = (p) => (isAbsolute(p) ? p : join(ROOT, p));

if (!sourcePath) fail("--source is required");
if (!sourceSha) fail("--sha is required");
const sha = sourceSha;

const fullSourcePath = resolvePath(sourcePath);
if (!existsSync(fullSourcePath)) fail(`source not found: ${fullSourcePath}`);

/** @type {Record<string, Record<string, string>>} */
let tokens = {};
try {
  tokens = JSON.parse(readFileSync(fullSourcePath, "utf-8"));
} catch (e) {
  fail(`source malformed: ${e instanceof Error ? e.message : String(e)}`);
}

// Required tokens (each list names what the site actually consumes).
const REQUIRED_FLUID_TOKENS = [
  "typography-fluid-display-base",
  "typography-fluid-h1-base",
  "typography-fluid-h2-base",
  "typography-fluid-h3-base",
  "typography-fluid-lede-base",
  "typography-fluid-body-base",
  "typography-fluid-caption-base",
];
const REQUIRED_SIZE_TOKENS = ["typography-size-4xl-base", "typography-size-5xl-base"];
const REQUIRED_FAMILY_TOKENS = ["typography-family-sans-base", "typography-family-mono-base"];
// videsign ADR-005: the hero scale is the one sanctioned billboard — validated
// separately (exactly 5.25rem) instead of the 3.5rem gate.
const HERO_TOKEN = "typography-fluid-hero-base";
const STANDARD_FLUID_CEILING_REM = 3.5;
const HERO_MAX_REM = 5.25;
// videsign ADR-004: persona identity accents (canonical emitted names only).
const REQUIRED_PERSONA_TOKENS = [
  "persona-accent-violet-base",
  "persona-accent-wisteria-base",
  "persona-accent-xylia-base",
  "persona-accent-yarrow-base",
  "persona-accent-zinnia-base",
];
const REQUIRED_LAYOUT_TOKENS = ["layout-width-content-base"];
// videsign ADR-006/008: crystal glass, ambient layer, concentric radii, motion.
const REQUIRED_EFFECT_TOKENS = [
  "glass-crystal-surface-base",
  "glass-crystal-surface-hover",
  "glass-crystal-rim-base",
  "glass-crystal-rim-hover",
  "glass-crystal-highlight-base",
  "glass-crystal-sheen-base",
  "glass-crystal-shadow-base",
  "glass-crystal-backdrop-base",
  "glass-crystal-core-base",
  "glass-crystal-solid-base",
  "ambient-glow-violet-base",
  // Deprecated name. The site aliases this to ambient-glow-wisteria-base until
  // the videsign re-sync emits the successor. Keep it required so the current
  // source snapshot still syncs.
  "ambient-glow-teal-base",
  "ambient-dots-base",
];
const REQUIRED_SPACING_TOKENS = ["layout-radius-glass-base", "layout-padding-bezel-base"];
const REQUIRED_TRANSITION_TOKENS = [
  "transition-duration-entrance-base",
  "transition-easing-standard-base",
  "transition-easing-spring-base",
];

/** @param {string} name @returns {Record<string, string>} */
const category = (name) => {
  const group = tokens[name];
  if (!group) fail(`missing ${name} category`);
  return group;
};
const typography = category("typography");
const size = category("size");
const colors = category("colors");
const effects = category("effects");
const spacing = category("spacing");
const transition = category("transition");

/** @param {Record<string, string>} group @param {string[]} names @param {string} label */
const need = (group, names, label) => {
  for (const token of names) {
    if (!group[token]) fail(`missing required token: ${label}${token}`);
  }
};
need(typography, [...REQUIRED_FLUID_TOKENS, ...REQUIRED_SIZE_TOKENS, ...REQUIRED_FAMILY_TOKENS, HERO_TOKEN], "");
need(colors, REQUIRED_PERSONA_TOKENS, "colors.");
need(size, REQUIRED_LAYOUT_TOKENS, "size.");
need(effects, REQUIRED_EFFECT_TOKENS, "effects.");
need(spacing, REQUIRED_SPACING_TOKENS, "spacing.");
need(transition, REQUIRED_TRANSITION_TOKENS, "transition.");

// Verify 5xl = 3.5rem (ceiling)
if (typography["typography-size-5xl-base"] !== "3.5rem") {
  fail(`5xl must be 3.5rem, got: ${typography["typography-size-5xl-base"]}`);
}

/** Last clamp() argument in rem, or null when the value is not a rem-capped clamp(). @param {unknown} value @returns {number | null} */
function clampMaxRem(value) {
  const match = String(value).match(/^clamp\(.+,\s*([\d.]+)rem\)$/);
  return match?.[1] ? parseFloat(match[1]) : null;
}

// Every fluid-* token is checked, not only the named ones: a token added later
// must not slip past the ceiling. Unparseable values fail instead of passing.
const fluidNames = Object.keys(typography).filter((name) => name.startsWith("typography-fluid-"));
for (const name of fluidNames) {
  const max = clampMaxRem(typography[name]);
  if (max === null) fail(`${name} is not a clamp() capped in rem: ${typography[name]}`);
  if (name === HERO_TOKEN) {
    // videsign ADR-005: the hero token is the sanctioned billboard exception.
    if (max !== HERO_MAX_REM) fail(`hero token max must be ${HERO_MAX_REM}rem (ADR-005), got: ${typography[name]}`);
  } else if (max > STANDARD_FLUID_CEILING_REM) {
    fail(`${name} max ${max}rem exceeds ${STANDARD_FLUID_CEILING_REM}rem ceiling`);
  }
}

// Canonical content width (videsign ADR-005 alias mapping): 80rem.
if (size["layout-width-content-base"] !== "80rem") {
  fail(`layout-width-content-base must be 80rem, got: ${size["layout-width-content-base"]}`);
}

// Concentric double bezel (videsign ADR-008): 20px shell = 6px padding + 14px core.
if (spacing["layout-radius-glass-base"] !== "20px" || spacing["layout-padding-bezel-base"] !== "6px") {
  fail("glass shell must be 20px with 6px bezel padding (concentric with the 14px core)");
}

/** @param {string} what */
const provenance = (what) => [
  `/* GENERATED BY scripts/sync-videsign-tokens.mjs — DO NOT EDIT. */`,
  `/* Source: Vidoxlabs/videsign at ${sha} */`,
  `/* Generation: npm run tokens (in videsign repo) */`,
  `/* Sync: node scripts/sync-videsign-tokens.mjs --source videsign-tokens-source.json --glass videsign-glass-source.css --sha <SHA> */`,
  `/* Artifact: ${what} */`,
];

// Generate tokens CSS
const outputPath = outArg ? resolvePath(outArg) : join(ROOT, "src/styles/videsign-tokens.css");
const lines = [...provenance("tokens"), ":root {"];
for (const [cat, entries] of Object.entries(tokens)) {
  for (const [key, value] of Object.entries(entries)) {
    lines.push(`  --vi-${cat}-${key}: ${value};`);
  }
}
lines.push("}");
writeFileSync(outputPath, lines.join("\n") + "\n");
console.log(`[tokens] wrote ${outputPath}`);

// Generate glass CSS (verbatim videsign stylesheet + provenance header)
let glassNote = "glass: not requested";
if (glassPath) {
  const fullGlassPath = resolvePath(glassPath);
  if (!existsSync(fullGlassPath)) fail(`glass source not found: ${fullGlassPath}`);
  const glass = readFileSync(fullGlassPath, "utf-8");
  // Safari ignores custom properties inside -webkit-backdrop-filter, so the
  // stylesheet must carry literal declarations for both spellings.
  if (!/-webkit-backdrop-filter:\s*blur\(/.test(glass) || !/[^-]backdrop-filter:\s*blur\(/.test(glass)) {
    fail("glass source lacks literal prefixed and unprefixed backdrop-filter declarations");
  }
  if (!glass.includes(".vi-glass-shell") || !glass.includes("prefers-reduced-transparency")) {
    fail("glass source lacks the shell class or the reduced-transparency fallback");
  }
  const glassOut = glassOutArg ? resolvePath(glassOutArg) : join(ROOT, "src/styles/videsign-glass.css");
  // Drop the generator banner. The sync provenance header replaces it, and the
  // leftover "Run npm run tokens" source line would contradict that header.
  const body = glass
    .replace(/^\/\* GENERATED BY scripts\/generate-tokens\.js[^\n]*\n/, "")
    .replace(/^\/\* Source: DESIGN\.md effects\/spacing tokens \(ADR-006\)\. Run `npm run tokens` to regenerate\. \*\/\n/, "");
  writeFileSync(glassOut, [...provenance("glass"), body.trimEnd(), ""].join("\n"));
  console.log(`[tokens] wrote ${glassOut}`);
  glassNote = "glass: literal backdrop declarations + fallbacks verified";
}

const required =
  REQUIRED_FLUID_TOKENS.length + REQUIRED_SIZE_TOKENS.length + REQUIRED_FAMILY_TOKENS.length + 1 +
  REQUIRED_PERSONA_TOKENS.length + REQUIRED_LAYOUT_TOKENS.length + REQUIRED_EFFECT_TOKENS.length +
  REQUIRED_SPACING_TOKENS.length + REQUIRED_TRANSITION_TOKENS.length;
if (!outArg && !glassOutArg) {
  const standardFile = join(ROOT, "videsign-standard-source.json");
  if (existsSync(standardFile)) {
    const standard = JSON.parse(readFileSync(standardFile, "utf8"));
    if (standard.meta == null || typeof standard.meta !== "object") standard.meta = {};
    if (standard.meta.pinnedSha !== sha) {
      standard.meta.pinnedSha = sha;
      writeFileSync(standardFile, `${JSON.stringify(standard, null, 2)}\n`);
    }
  }
  syncViDesignStandardFiles(ROOT);
}

console.log(`[tokens] provenance: Vidoxlabs/videsign@${sha.substring(0, 12)}`);
console.log(`[tokens] verified: ${required} required tokens present`);
console.log(`[tokens] fluid: ${fluidNames.length} fluid tokens checked; standard <= ${STANDARD_FLUID_CEILING_REM}rem, hero = ${HERO_MAX_REM}rem (ADR-005)`);
console.log(`[tokens] ${glassNote}`);
